    def to_number(self, v):
        if isinstance(v, (int,float)):
            return v
        if isinstance(v, str):
            try:
                # try int first?
                if '.' in v or 'e' in v.lower():
                    return float(v)
                else:
                    return int(v)
            except:
                return LuaNil
        return LuaNil

def lua_tostring(v):
    if v is LuaNil: return "nil"
    if v is True: return "true"
    if v is False: return "false"
    if isinstance(v, (int,float)): return str(v)
    if isinstance(v, str): return v
    if isinstance(v, LuaTable): return f"table: 0x{id(v):x}"
    if isinstance(v, LuaFunction): return f"function: 0x{id(v):x}"
    if isinstance(v, LuaCoroutine): return f"thread: 0x{id(v):x}"
    return str(v)

