    def peek(self, n=0):
        if self.pos+n < self.len:
            return self.text[self.pos+n]
        return '\0'
    def advance(self, n=1):
        for i in range(n):
            if self.pos < self.len:
                c = self.text[self.pos]
                self.pos += 1
                if c == '\n':
                    self.line += 1
                    self.col = 1
                else:
