                self.advance(1+eq+1)  # skip [==[
                # find closing
                end_pat = ']' + '='*eq + ']'
                idx = self.text.find(end_pat, self.pos)
                if idx == -1:
                    raise LuaError(f"{self.chunkname}:{start_line}: unfinished long string (near '<eof>')")
                content = self.text[self.pos:idx]
                # handle first newline skip?
                if content.startswith('\n') or content.startswith('\r'):
                    # Lua discards first newline
                    if content.startswith('\r\n'):
                        content = content[2:]
                    elif content[0] in '\n\r':
                        content = content[1:]
                self.line += content.count('\n') + self.text[self.pos:idx].count('\n') - content.count('\n') # approximate
                self.pos = idx + len(end_pat)
                # update line for content's newlines
                # Actually we already counted, but need accurate
                # For simplicity, recount from original
                return Token('STRING', content, start_line, start_col)
        # String
        if c == '"' or c == "'":
            quote = c
            start_line = self.line
            start_col = self.col
            self.advance()
            s = ""
            while self.pos < self.len:
                ch = self.text[self.pos]
                if ch == '\\':
                    self.advance()
                    if self.pos >= self.len:
                        break
                    esc = self.text[self.pos]
                    self.advance()
                    if esc == 'a': s += '\a'
                    elif esc == 'b': s += '\b'
                    elif esc == 'f': s += '\f'
                    elif esc == 'n': s += '\n'
                    elif esc == 'r': s += '\r'
                    elif esc == 't': s += '\t'
                    elif esc == 'v': s += '\v'
                    elif esc == '\\': s += '\\'
                    elif esc == '"': s += '"'
                    elif esc == "'": s += "'"
                    elif esc == '\n': s += '\n'
                    elif esc == '\r':
                        if self.peek() == '\n':
                            self.advance()
                        s += '\n'
                    elif esc == 'z':
                        # skip whitespace
                        while self.pos < self.len and self.text[self.pos] in ' \t\r\n\v\f':
                            self.advance()
                    elif esc == 'x':
                        # \xXX
                        hexd = self.text[self.pos:self.pos+2]
                        if len(hexd)==2 and all(h in '0123456789abcdefABCDEF' for h in hexd):
                            s += chr(int(hexd,16))
                            self.advance(2)
                        else:
                            raise LuaError(f"{self.chunkname}:{self.line}: hexadecimal digit expected near '\\x'")
                    elif esc == 'u':
                        # \u{XXX}
                        if self.peek() == '{':
                            self.advance()
                            start = self.pos
                            while self.pos < self.len and self.text[self.pos] != '}':
                                self.advance()
                            hexd = self.text[start:self.pos]
                            if self.pos < self.len and self.text[self.pos]=='}':
                                self.advance()
                            try:
                                code = int(hexd,16)
                                if code>0x10FFFF:
                                    raise ValueError
                                s += chr(code)
                            except:
                                raise LuaError(f"{self.chunkname}:{self.line}: UTF-8 value too large near '\\u'")
                        else:
                            raise LuaError(f"{self.chunkname}:{self.line}: missing '{{' near '\\u'")
                    elif esc.isdigit():
                        # \ddd up to 3 digits
                        d = esc
                        for k in range(2):
                            if self.pos < self.len and self.text[self.pos].isdigit():
                                d += self.text[self.pos]
                                self.advance()
                            else:
                                break
                        val = int(d)
                        if val>255:
                            raise LuaError(f"{self.chunkname}:{self.line}: decimal escape too large near '\\{d}'")
                        s += chr(val)
                    else:
                        s += esc
                elif ch == quote:
                    self.advance()
                    break
                elif ch == '\n' or ch == '\r':
                    raise LuaError(f"{self.chunkname}:{self.line}: unfinished string near '<eof>'")
                else:
                    s += ch
                    self.advance()
            else:
                raise LuaError(f"{self.chunkname}:{self.line}: unfinished string near '<eof>'")
            return Token('STRING', s, start_line, start_col)
        # Number: hex or decimal
        # Check for 0x
        if c == '0' and self.peek(1) in 'xX':
            start = self.pos
            start_line = self.line
            self.advance(2)
            # hex digits
            has_dot = False
            has_p = False
            while self.pos < self.len:
                ch = self.text[self.pos]
                if ch in '0123456789abcdefABCDEF':
                    self.advance()
                elif ch == '.' and not has_dot:
                    has_dot = True
                    self.advance()
                elif ch in 'pP' and not has_p:
                    has_p = True
                    self.advance()
                    if self.pos < self.len and self.text[self.pos] in '+-':
                        self.advance()
                else:
                    break
            num_str = self.text[start:self.pos]
            try:
                # Try to parse as integer if no dot/p
                if '.' not in num_str and 'p' not in num_str.lower():
                    val = int(num_str, 16)
                else:
                    # hex float
                    val = float.fromhex(num_str)
                    # need to handle? float.fromhex can parse
                    # But Lua's hex float uses p, float.fromhex expects same
                    pass
            except:
                val = 0
            return Token('NUMBER', val, start_line, 1)
        # Decimal number
        if c.isdigit() or (c == '.' and self.peek(1).isdigit()):
            start = self.pos
            start_line = self.line
            # parse
            has_dot = False
            has_e = False
            while self.pos < self.len:
                ch = self.text[self.pos]
                if ch.isdigit():
                    self.advance()
                elif ch == '.' and not has_dot and self.peek(1) != '.':  # not ..
                    has_dot = True
                    self.advance()
                elif ch in 'eE' and not has_e:
                    has_e = True
                    self.advance()
                    if self.pos < self.len and self.text[self.pos] in '+-':
                        self.advance()
                else:
                    break
            num_str = self.text[start:self.pos]
            # Separate int vs float
            try:
                if '.' not in num_str and 'e' not in num_str.lower():
                    val = int(num_str)
                    # if too large, convert to float? Lua ints are 64-bit
                    if val > 2**63-1 or val < -2**63:
                        val = float(num_str)
                else:
                    val = float(num_str)
            except:
                val = 0
            return Token('NUMBER', val, start_line, 1)
        # Name or keyword
        if c.isalpha() or c == '_':
            start = self.pos
            start_line = self.line
            while self.pos < self.len and (self.text[self.pos].isalnum() or self.text[self.pos]=='_'):
                self.advance()
            name = self.text[start:self.pos]
            if name in ('and','break','do','else','elseif','end','false','for','function','goto','if','in','local','nil','not','or','repeat','return','then','true','until','while'):
                return Token(name.upper(), name, start_line, 1)
            else:
                return Token('NAME', name, start_line, 1)
        # Symbols
        # Check multi-char
        three = self.text[self.pos:self.pos+3]
        two = self.text[self.pos:self.pos+2]
        one = c
        # Order: ... first, then .., then //, >>, <<, ==, ~=, <=, >=, ::
        if three == '...':
            self.advance(3)
            return Token('TDOTS', '...', self.line, 1)
        if two in ('//','>>','<<','==','~=','<=','>=','::'):
            self.advance(2)
            return Token(two, two, self.line, 1)
        if two == '..':
            self.advance(2)
            return Token('DOTDOT', '..', self.line, 1)
        # Single
        self.advance()
        if one in '+-*/%^#&|~<>=(){}[];:,.':
            return Token(one, one, self.line, 1)
        # Unknown
        raise LuaError(f"{self.chunkname}:{self.line}: unexpected symbol near '{one}'")
    def tokenize(self):
        tokens = []
        while True:
            tok = self.next_token()
            tokens.append(tok)
            if tok.typ == 'EOF':
                break
        return tokens

# Parser
class Parser:
    def __init__(self, tokens, chunkname="=(command line)"):
        self.tokens = tokens
        self.pos = 0
        self.chunkname = chunkname
    def peek(self, n=0):
        if self.pos+n < len(self.tokens):
            return self.tokens[self.pos+n]
        return self.tokens[-1]
    def advance(self):
        t = self.tokens[self.pos]
        self.pos += 1
        return t
    def match(self, typ):
        if self.peek().typ == typ:
            return self.advance()
        return None
    def expect(self, typ):
        t = self.peek()
        if t.typ != typ:
            raise LuaError(f"{self.chunkname}:{t.line}: '{typ}' expected (to close '{typ}' at line {t.line}) near '{t.val}'" if t.typ!='EOF' else f"{self.chunkname}:{t.line}: '{typ}' expected (to close '{typ}' at line {t.line}) near '<eof>'")
        return self.advance()
    def parse_chunk(self):
        block = self.parse_block()
        self.expect('EOF')
        return {'type':'chunk','body':block}
    def parse_block(self):
        stmts = []
        while self.peek().typ not in ('EOF','END','ELSE','ELSEIF','UNTIL'):
            if self.peek().typ == 'RETURN':
                stmts.append(self.parse_return())
                # return should be last? but we continue
                # In Lua, return must be last statement in block, but we allow
                # Check for ';'
                if self.peek().typ == ';':
                    self.advance()
                break
            elif self.peek().typ == 'BREAK':
                self.advance()
                if self.peek().typ == ';': self.advance()
                stmts.append({'type':'break'})
            elif self.peek().typ == 'GOTO':
                self.advance()
                name = self.expect('NAME')
                if self.peek().typ == ';': self.advance()
                stmts.append({'type':'goto','label':name.val})
            elif self.peek().typ == '::':
                self.advance()
                name = self.expect('NAME')
                self.expect('::')
                stmts.append({'type':'label','name':name.val})
            else:
                # need to handle `;` empty statement
                if self.peek().typ == ';':
                    self.advance()
                    continue
                stmt = self.parse_statement()
                if stmt:
                    stmts.append(stmt)
                # optional ;
                if self.peek().typ == ';':
                    self.advance()
        return stmts
    def parse_return(self):
        self.expect('RETURN')
        exps = []
        if self.peek().typ not in ('EOF','END','ELSE','ELSEIF','UNTIL',';'):
            exps = self.parse_explist()
            if self.peek().typ == ';':
                self.advance()
        return {'type':'return','exps':exps}
    def parse_statement(self):
        t = self.peek()
        if t.typ == 'LOCAL':
            return self.parse_local()
        if t.typ == 'FUNCTION':
            return self.parse_functiondef(is_local=False)
        if t.typ == 'IF':
            return self.parse_if()
        if t.typ == 'WHILE':
            return self.parse_while()
        if t.typ == 'REPEAT':
            return self.parse_repeat()
        if t.typ == 'FOR':
            return self.parse_for()
        if t.typ == 'DO':
            self.advance()
            block = self.parse_block()
            self.expect('END')
            return {'type':'do','body':block}
        # Try assignment or function call
        # Need to lookahead: primary exp then check for = or ,
        # Save pos
        saved = self.pos
        try:
            # try to parse var list
            # For function call vs assignment, we need to distinguish
            # Parse prefix exp
            # This is complex, we will parse expression and then check
            # For now, try to parse `functioncall` vs `assignment`
            # We'll parse a list of vars or exps
            # Use approach: parse primary, then see if next is = or ,
            # Actually Lua's assignment: varlist '=' explist
            # var is: NAME | prefixexp '[' exp ']' | prefixexp '.' NAME
            # So we need to try.
            # We'll attempt to parse assignment first, else fall back to call
            # Save and try assignment
            # For simplicity, we will parse the statement as exp and then decide
            exp = self.parse_exp()
            # Check if next is '=' or ','
            if self.peek().typ in ('=',','):
                # It's assignment, rewind and parse varlist
                self.pos = saved
                return self.parse_assignment()
            else:
                # It's expression statement (function call)
                # Need to ensure exp is a call
                if exp['type'] not in ('call','methodcall'):
                    raise LuaError(f"{self.chunkname}:{t.line}: syntax error near '{t.val}'")
                return {'type':'callstmt','call':exp}
        except Exception as e:
            # if it's LuaError, re-raise
            if isinstance(e, LuaError):
                raise
            self.pos = saved
            # try assignment
            return self.parse_assignment()
    def parse_local(self):
        self.expect('LOCAL')
        if self.peek().typ == 'FUNCTION':
            self.advance()
            name = self.expect('NAME')
            # params and body
            params, vararg, body = self.parse_funcbody()
            return {'type':'localfunc','name':name.val,'params':params,'vararg':vararg,'body':body}
        else:
            # local namelist ['=' explist]
            names = []
            names.append(self.expect('NAME').val)
            while self.peek().typ == ',':
                self.advance()
                names.append(self.expect('NAME').val)
            exps = []
            if self.peek().typ == '=':
                self.advance()
                exps = self.parse_explist()
            return {'type':'local','names':names,'exps':exps}
    def parse_functiondef(self, is_local=False):
        self.expect('FUNCTION')
        # funcname: NAME {'.' NAME} [':' NAME]
        name = self.expect('NAME').val
        is_method = False
        method_self = None
        while self.peek().typ == '.':
            self.advance()
            n = self.expect('NAME').val
            name = name + '.' + n
        if self.peek().typ == ':':
            self.advance()
            n = self.expect('NAME').val
            is_method = True
            method_self = n
            name = name + ':' + n
        params, vararg, body = self.parse_funcbody()
        if is_method:
            # add self param
            params = ['self'] + params
        return {'type':'functiondef','name':name,'params':params,'vararg':vararg,'body':body,'is_method':is_method}
    def parse_funcbody(self):
        self.expect('(')
        params = []
        vararg = False
        if self.peek().typ != ')':
            if self.peek().typ == 'TDOTS':
                self.advance()
                vararg = True
            else:
                params.append(self.expect('NAME').val)
                while self.peek().typ == ',':
                    self.advance()
                    if self.peek().typ == 'TDOTS':
                        self.advance()
                        vararg = True
                        break
                    else:
                        params.append(self.expect('NAME').val)
        self.expect(')')
        block = self.parse_block()
        self.expect('END')
        return params, vararg, block
    def parse_if(self):
        self.expect('IF')
        cond = self.parse_exp()
        self.expect('THEN')
        then_block = self.parse_block()
        elseif_blocks = []
        else_block = None
        while self.peek().typ == 'ELSEIF':
            self.advance()
            c = self.parse_exp()
            self.expect('THEN')
            b = self.parse_block()
            elseif_blocks.append((c,b))
        if self.peek().typ == 'ELSE':
            self.advance()
            else_block = self.parse_block()
        self.expect('END')
        return {'type':'if','cond':cond,'then':then_block,'elseif':elseif_blocks,'else':else_block}
    def parse_while(self):
        self.expect('WHILE')
        cond = self.parse_exp()
        self.expect('DO')
        body = self.parse_block()
        self.expect('END')
        return {'type':'while','cond':cond,'body':body}
    def parse_repeat(self):
        self.expect('REPEAT')
        body = self.parse_block()
        self.expect('UNTIL')
        cond = self.parse_exp()
        return {'type':'repeat','body':body,'cond':cond}
    def parse_for(self):
        self.expect('FOR')
        name = self.expect('NAME').val
        if self.peek().typ == '=':
            self.advance()
            start = self.parse_exp()
            self.expect(',')
            limit = self.parse_exp()
            step = None
            if self.peek().typ == ',':
                self.advance()
                step = self.parse_exp()
            self.expect('DO')
            body = self.parse_block()
            self.expect('END')
            return {'type':'fornum','var':name,'start':start,'limit':limit,'step':step,'body':body}
        else:
            # for generic
            # namelist
            names = [name]
            while self.peek().typ == ',':
                self.advance()
                names.append(self.expect('NAME').val)
            self.expect('IN')
            exps = self.parse_explist()
            self.expect('DO')
            body = self.parse_block()
            self.expect('END')
            return {'type':'forin','names':names,'exps':exps,'body':body}
    def parse_assignment(self):
        # varlist '=' explist
        vars = []
        # parse first var
        vars.append(self.parse_var())
        while self.peek().typ == ',':
            self.advance()
            vars.append(self.parse_var())
        self.expect('=')
        exps = self.parse_explist()
        return {'type':'assign','vars':vars,'exps':exps}
    def parse_var(self):
        # var: NAME | prefixexp '[' exp ']' | prefixexp '.' NAME
        # For simplicity, we will parse primary and then handle indexing
        # But we need to distinguish var vs exp
        # We'll parse prefix
        # If next token is NAME and following is not '[' or '.' then it's just NAME
        # Otherwise, parse as exp and then check
        # Simpler: parse prefixexp and then see
        # For now, just handle NAME case and prefix '.' '['
        # We'll use parse_prefix to get base, then handle suffix
        # But this is getting complex, we will implement a simple version: var is either NAME or table access
        # We'll parse as: primary = NAME or '(' exp ')' then { '.' NAME or '[' exp ']' }
        # For var, we need at least one suffix or just NAME
        # We'll just call parse_prefixexp and then check if it's var-like
        exp = self.parse_prefixexp()
        # exp should be var
        # For our interpreter, we will treat var as exp node with type var or index
        return exp
    def parse_explist(self):
        exps = [self.parse_exp()]
        while self.peek().typ == ',':
            self.advance()
            exps.append(self.parse_exp())
        return exps
    def parse_exp(self, min_prec=0):
        # Pratt parser
        # Parse prefix
        tok = self.peek()
        # handle unary
        if tok.typ in ('NOT','#','-','~'):
            self.advance()
            # unary has high precedence
            rhs = self.parse_exp(12)  # unary precedence 12?
            node = {'type':'unary','op':tok.val,'exp':rhs}
            left = node
        elif tok.typ == 'TDOTS':
            self.advance()
            left = {'type':'vararg'}
        elif tok.typ == 'NIL':
            self.advance()
            left = {'type':'nil'}
        elif tok.typ == 'TRUE':
            self.advance()
            left = {'type':'boolean','val':True}
        elif tok.typ == 'FALSE':
            self.advance()
            left = {'type':'boolean','val':False}
        elif tok.typ == 'NUMBER':
            self.advance()
            left = {'type':'number','val':tok.val}
        elif tok.typ == 'STRING':
            self.advance()
            left = {'type':'string','val':tok.val}
        elif tok.typ == 'FUNCTION':
            self.advance()
            params, vararg, body = self.parse_funcbody()
            left = {'type':'function','params':params,'vararg':vararg,'body':body}
        elif tok.typ == '{':
            left = self.parse_tableconstructor()
        elif tok.typ == '(':
            self.advance()
            exp = self.parse_exp()
            self.expect(')')
            left = exp
        elif tok.typ == 'NAME':
            # could be var or call
            left = self.parse_prefixexp()
        else:
            raise LuaError(f"{self.chunkname}:{tok.line}: unexpected symbol near '{tok.val}'")
        # Infix
        while True:
            op = self.peek()
            # Check for binary operators
            prec = self.get_precedence(op.typ if op.typ in ('AND','OR') else op.val)
            if prec is None or prec < min_prec:
                break
            # For right associative, next_prec = prec, else prec+1
            is_right = op.val in ('^','..')
            next_prec = prec if is_right else prec+1
            self.advance()
            # Special handling for `and` `or` which are keywords
            if op.typ in ('AND','OR'):
                rhs = self.parse_exp(next_prec)
                left = {'type':'binary','op':op.val,'left':left,'right':rhs}
            else:
                rhs = self.parse_exp(next_prec)
                left = {'type':'binary','op':op.val,'left':left,'right':rhs}
            # Need to handle call suffix? Actually after parsing infix, we might have table/function suffixes?
            # But those were handled in prefixexp, not here.
        return left
    def get_precedence(self, op):
        # returns precedence number
        if op == 'or': return 1
        if op == 'and': return 2
        if op in ('<','>','<=','>=','~=', '=='): return 3
        if op == '|': return 4
        if op == '~': return 5  # binary ~
        if op == '&': return 6
        if op in ('<<','>>'): return 7
        if op == '..': return 8  # right
        if op in ('+','-'): return 9
        if op in ('*','/','//','%'): return 10
        if op in ('^',): return 12  # right, highest before unary
        # unary handled separately
        return None
    def parse_prefixexp(self):
        # prefixexp: var or functioncall or '(' exp ')'
        # var: NAME | prefixexp '[' exp ']' | prefixexp '.' NAME
        # functioncall: prefixexp args | prefixexp ':' NAME args
        # So we need to parse base then loop
        if self.peek().typ == '(':
            self.advance()
            exp = self.parse_exp()
            self.expect(')')
            base = exp
        elif self.peek().typ == 'NAME':
            name = self.advance().val
            base = {'type':'var','name':name}
        else:
            raise LuaError(f"{self.chunkname}:{self.peek().line}: unexpected symbol near '{self.peek().val}'")
        while True:
            if self.peek().typ == '.':
                self.advance()
                field = self.expect('NAME').val
                base = {'type':'index','table':base,'key':{'type':'string','val':field}}
            elif self.peek().typ == '[':
                self.advance()
                idx = self.parse_exp()
                self.expect(']')
                base = {'type':'index','table':base,'key':idx}
            elif self.peek().typ == ':':
                self.advance()
                method = self.expect('NAME').val
                args = self.parse_args()
                base = {'type':'methodcall','table':base,'method':method,'args':args}
            elif self.peek().typ in ('(','{','STRING'):
                args = self.parse_args()
                base = {'type':'call','func':base,'args':args}
            else:
                break
        return base
    def parse_args(self):
        if self.peek().typ == '(':
            self.advance()
            args = []
            if self.peek().typ != ')':
                args = self.parse_explist()
            self.expect(')')
            return args
        elif self.peek().typ == '{':
            t = self.parse_tableconstructor()
            return [t]
        elif self.peek().typ == 'STRING':
            s = self.advance()
            return [{'type':'string','val':s.val}]
        else:
            raise LuaError(f"{self.chunkname}:{self.peek().line}: function arguments expected near '{self.peek().val}'")
    def parse_tableconstructor(self):
        self.expect('{')
        fields = []
        while self.peek().typ != '}':
            if self.peek().typ == 'EOF':
                raise LuaError(f"{self.chunkname}:{self.peek().line}: '}}' expected (to close '{{' at line {self.peek().line}) near '<eof>'")
            # Check for '[' exp ']' '=' exp
            if self.peek().typ == '[':
                self.advance()
                k = self.parse_exp()
                self.expect(']')
                self.expect('=')
                v = self.parse_exp()
                fields.append({'type':'field_kv','key':k,'val':v})
            elif self.peek().typ == 'NAME' and self.peek(1).typ == '=':
                k = self.advance().val
                self.advance()  # =
                v = self.parse_exp()
                fields.append({'type':'field_kv','key':{'type':'string','val':k},'val':v})
            else:
                v = self.parse_exp()
                fields.append({'type':'field_val','val':v})
            if self.peek().typ in (',',';'):
                self.advance()
            else:
                # maybe next is }
                pass
        self.expect('}')
        return {'type':'table','fields':fields}

# Interpreter

class ReturnException(Exception):
    def __init__(self, vals):
        self.vals = vals
class BreakException(Exception):
    pass
class GotoException(Exception):
    def __init__(self, label):
        self.label = label

class Interpreter:
    def __init__(self, state, chunkname):
        self.state = state
        self.chunkname = chunkname
        self.env_stack = [{}]  # local scopes
        self.labels = {}  # label -> index in block? For goto
        self.loop_stack = []  # for break
    def push_env(self):
        self.env_stack.append({})
    def pop_env(self):
        self.env_stack.pop()
    def set_local(self, name, val):
        # set in current scope or find existing?
        # For assignment to local, we need to find where it's defined
        for scope in reversed(self.env_stack):
            if name in scope:
                scope[name] = val
                return
        # if not found, set in current (maybe global? But local should be in current scope)
        self.env_stack[-1][name] = val
    def get_local(self, name):
        for scope in reversed(self.env_stack):
            if name in scope:
                return scope[name]
        return None
    def get_var(self, name):
        # check locals first
        for scope in reversed(self.env_stack):
            if name in scope:
                return scope[name]
        # then check globals
        v = self.state.globals.get(name)
        if v is not LuaNil:
            return v
        # Also check env upvalue? For now
        return LuaNil
    def set_var(self, name, val, is_local_decl=False):
        # if is_local_decl, always set in current scope
        if is_local_decl:
            self.env_stack[-1][name] = val
            return
        # else, try to find local
        for scope in reversed(self.env_stack):
            if name in scope:
                scope[name] = val
                return
        # otherwise set global
        self.state.globals.set(name, val)
    def eval_exp(self, node):
        typ = node['type']
        if typ == 'nil':
            return LuaNil
        if typ == 'boolean':
            return node['val']
        if typ == 'number':
            return node['val']
        if typ == 'string':
            return node['val']
        if typ == 'var':
            return self.get_var(node['name'])
        if typ == 'vararg':
            # need to handle vararg
            # For now, return nil or expand?
            # We need to track varargs in function
            # We'll store varargs in a special variable?
            # For now, return LuaNil
            # Actually vararg should be handled by function call expansion
            # We'll return a tuple marker?
            return LuaNil  # placeholder
        if typ == 'table':
            tbl = LuaTable()
            # fields
            array_idx = 1
            for f in node['fields']:
                if f['type'] == 'field_val':
                    v = self.eval_exp(f['val'])
                    # if v is multiple values (from call), need to handle?
                    # For now, if v is tuple, expand?
                    if isinstance(v, tuple):
                        for vi in v:
                            tbl.set(array_idx, vi)
                            array_idx += 1
                    else:
                        tbl.set(array_idx, v)
                        array_idx += 1
                elif f['type'] == 'field_kv':
                    k = self.eval_exp(f['key'])
                    v = self.eval_exp(f['val'])
                    tbl.set(k, v)
            return tbl
        if typ == 'index':
            tbl = self.eval_exp(node['table'])
            key = self.eval_exp(node['key'])
            if isinstance(tbl, LuaTable):
                return tbl.get(key)
            elif isinstance(tbl, str):
                # string indexing? Not needed
                return LuaNil
            else:
                # try metatable __index?
                # For now, return nil
                return LuaNil
        if typ == 'unary':
            op = node['op']
            val = self.eval_exp(node['exp'])
            if op == 'not':
                return False if self.is_truthy(val) else True
            if op == '#':
                if isinstance(val, LuaTable):
                    return val.length()
                if isinstance(val, str):
                    return len(val)
                # error?
                raise LuaError(f"attempt to get length of a {self.lua_type(val)} value")
            if op == '-':
                if isinstance(val, (int, float)):
                    return -val
                # try metamethod __unm?
                raise LuaError(f"attempt to perform arithmetic on a {self.lua_type(val)} value")
            if op == '~':
                if isinstance(val, int):
                    return ~val
                raise LuaError(f"attempt to perform bitwise operation on a {self.lua_type(val)} value")
            raise LuaError(f"unknown unary {op}")
        if typ == 'binary':
            op = node['op']
            # need short-circuit for and/or
            if op == 'and':
                left = self.eval_exp(node['left'])
                if not self.is_truthy(left):
                    return left
                else:
                    return self.eval_exp(node['right'])
            if op == 'or':
                left = self.eval_exp(node['left'])
                if self.is_truthy(left):
                    return left
                else:
                    return self.eval_exp(node['right'])
            left = self.eval_exp(node['left'])
            right = self.eval_exp(node['right'])
            return self.eval_binary(op, left, right)
        if typ == 'call':
            func = self.eval_exp(node['func'])
            args = []
            for a in node['args']:
                v = self.eval_exp(a)
                # handle vararg expansion? For now, if v is tuple, expand?
                if isinstance(v, tuple):
                    args.extend(v)
                else:
                    args.append(v)
            return self.call_func(func, args, node)
        if typ == 'methodcall':
            tbl = self.eval_exp(node['table'])
            method = node['method']
            # get method from tbl
            # tbl is table or string or etc.
            # For string, need to check string library?
            func = None
            if isinstance(tbl, LuaTable):
                func = tbl.get(method)
            elif isinstance(tbl, str):
                # string library
                # get from string metatable?
                # For now, look up in globals string table
                str_lib = self.state.globals.get("string")
                if isinstance(str_lib, LuaTable):
                    func = str_lib.get(method)
            else:
                # try metatable
                func = LuaNil
            args = [tbl]  # self
            for a in node['args']:
                v = self.eval_exp(a)
                if isinstance(v, tuple):
                    args.extend(v)
                else:
                    args.append(v)
            return self.call_func(func, args, node)
        if typ == 'function':
            # create closure
            # capture upvalues? For now, capture current env
            # We'll create LuaFunction with params, body, and captured env
            # Need to capture locals that are upvalues
            fn = LuaFunction(None, node['params'], node['vararg'], node['body'], dict(self.env_stack[-1]), chunkname=self.chunkname)
            # Also need to handle upvalues for recursion? Not needed
            return fn
        raise LuaError(f"unknown exp type {typ}")
    def is_truthy(self, v):
        return not (v is LuaNil or v is False)
    def lua_type(self, v):
        if v is LuaNil: return "nil"
        if isinstance(v, bool): return "boolean"
        if isinstance(v, (int,float)): return "number"
        if isinstance(v, str): return "string"
        if isinstance(v, LuaTable): return "table"
        if isinstance(v, LuaFunction) or callable(v): return "function"
        if isinstance(v, LuaCoroutine): return "thread"
        return "userdata"
    def eval_binary(self, op, a, b):
        # handle metamethods?
        # Try to handle numbers and strings
        # For arithmetic, try to convert strings to numbers?
        def to_number(v):
            if isinstance(v, (int,float)): return v
            if isinstance(v, str):
                try:
                    if '.' in v or 'e' in v.lower():
                        return float(v)
                    else:
                        return int(v)
                except: return None
            return None
        if op in ('+','-','*','/','%','^','//'):
            # try numeric
            na = to_number(a)
            nb = to_number(b)
            if na is None or nb is None:
                raise LuaError(f"attempt to perform arithmetic on a {self.lua_type(a)} value")
            if op == '+': return na + nb
            if op == '-': return na - nb
            if op == '*': return na * nb
            if op == '/':
                # always float division
                return float(na) / float(nb)
            if op == '//':
                return math.floor(float(na) / float(nb))
            if op == '%': return na % nb
            if op == '^': return na ** nb
            if op == '..':
                pass
        if op == '..':
            # string concat: convert to string
            sa = lua_tostring(a) if not isinstance(a, str) else a
            sb = lua_tostring(b) if not isinstance(b, str) else b
            # lua_tostring for numbers?
            if isinstance(a, (int,float)):
                sa = self.number_to_string(a)
            if isinstance(b, (int,float)):
                sb = self.number_to_string(b)
            return sa + sb
        if op in ('<<','>>','&','|','~'):
            # bitwise, need integers
            if not isinstance(a, int) or not isinstance(b, int):
                # try to convert float to int if it's integer-valued?
                if isinstance(a, float) and a.is_integer():
                    a = int(a)
                elif isinstance(a, str):
                    try: a=int(a)
                    except: raise LuaError(f"attempt to perform bitwise operation on a {self.lua_type(a)} value")
                else:
                    raise LuaError(f"attempt to perform bitwise operation on a {self.lua_type(a)} value")
                if isinstance(b, float) and b.is_integer():
                    b=int(b)
                elif isinstance(b, str):
                    try: b=int(b)
                    except: raise LuaError(f"attempt to perform bitwise operation on a {self.lua_type(b)} value")
                else:
                    raise LuaError(f"attempt to perform bitwise operation on a {self.lua_type(b)} value")
            if op == '<<': return a << b
            if op == '>>': return a >> b
            if op == '&': return a & b
            if op == '|': return a | b
            if op == '~': return a ^ b
        if op in ('==','~=','<','>','<=','>='):
            # handle == and ~= with raw equality first?
            # For simplicity, use Python equality but need to handle LuaNil, tables, etc.
            if op == '==':
                # Lua's == checks type and value, tables by reference
                # For numbers, need to handle int vs float?
                if type(a) != type(b):
                    # but int and float are both numbers, so check numeric equality
                    if isinstance(a, (int,float)) and isinstance(b, (int,float)):
                        return a == b
                    return False
                return a == b
            if op == '~=':
                if type(a) != type(b):
                    if isinstance(a, (int,float)) and isinstance(b, (int,float)):
                        return a != b
                    return True
                return a != b
            # ordering: need to handle strings and numbers
            # If both numbers, compare numerically
            if isinstance(a, (int,float)) and isinstance(b, (int,float)):
                if op == '<': return a < b
                if op == '>': return a > b
                if op == '<=': return a <= b
                if op == '>=': return a >= b
            if isinstance(a, str) and isinstance(b, str):
                if op == '<': return a < b
                if op == '>': return a > b
                if op == '<=': return a <= b
                if op == '>=': return a >= b
            raise LuaError(f"attempt to compare {self.lua_type(a)} with {self.lua_type(b)}")
        raise LuaError(f"unknown binary op {op}")
    def number_to_string(self, n):
        if isinstance(n, int):
            return str(n)
        # for float, use Lua's formatting: try to mimic?
        # Use repr but ensure it matches Lua's output for tests: we saw 0.0 for math.sin(0)
        # Python's repr for 0.0 is "0.0", good
        # For integers as float, Lua may print as "1.0"? But our earlier test with print(1) gave "1", not "1.0"
        # So we need to handle: if float is integer-valued, should we print as "1.0" or "1"? In Lua, 1.0 prints as "1.0" if it's a float, but 1 as integer prints as "1". However our numbers are Python ints/floats, we need to distinguish.
        # We'll just use Python's str: 1.0 -> "1.0", 1 -> "1"
        # But need to handle scientific?
        s = str(n)
        # Lua uses %g style, but we'll use str
        return s
    def call_func(self, func, args, call_node=None):
        # func could be LuaFunction, python callable, or LuaTable with __call
        if func is LuaNil or func is None:
            raise LuaError("attempt to call a nil value")
        if isinstance(func, LuaTable):
            # check __call metamethod
            mt = func.metatable
            if mt is not None and isinstance(mt, LuaTable):
                call = mt.get("__call")
                if call is not LuaNil:
                    # call metamethod with func as first arg
                    return self.call_func(call, [func]+args, call_node)
            raise LuaError(f"attempt to call a {self.lua_type(func)} value")
        if isinstance(func, LuaFunction):
            # create new env
            old_stack = self.env_stack
            # new scope for function
            new_env = {}
            # map params
            for i, pname in enumerate(func.params):
                if i < len(args):
                    new_env[pname] = args[i]
                else:
                    new_env[pname] = LuaNil
            # handle vararg
            if func.vararg:
                # extra args go to vararg
                varargs = args[len(func.params):]
                new_env['...'] = varargs  # store as list
                # also need to handle `...` expansion? We'll store
            else:
                # if not vararg but extra args are ignored
                pass
            # handle closure: need to merge func.env (captured) with new_env?
            # For simplicity, push new_env and also have access to globals and upvalues
            # We'll push new_env onto stack
            self.env_stack = self.env_stack + [new_env]
            # Also need to handle `self` for methods? Already handled via params
            try:
                # execute body
                result = self.exec_block(func.body)
                # if no return, return nil
                if result is None:
                    return LuaNil
                # result is tuple of return values
                if isinstance(result, tuple):
                    if len(result)==0:
                        return LuaNil
                    if len(result)==1:
                        return result[0]
                    return result
                return result
            except ReturnException as e:
                vals = e.vals
                if not vals:
                    return LuaNil
                if len(vals)==1:
                    return vals[0]
                return tuple(vals)
            except BreakException:
                raise LuaError("break outside loop")
            finally:
                self.env_stack = old_stack
        if callable(func):
            # Python function (stdlib)
            # Need to handle that func may be a method expecting LuaState?
            try:
                # Try to call with args
                # For stdlib functions, they expect (state, args) or just args?
                # We'll try to call with *args, and if it expects state, it will be first arg?
                # Our stdlib functions will be defined to take (args) and use closure for state
                # So we call func(*args)
                # But some functions need to know how many args?
                # We'll try
                if hasattr(func, '_is_lua_stdlib'):
                    return func(*args)
                else:
                    # generic python callable
                    res = func(*args)
                    if res is None:
                        return LuaNil
                    return res
            except LuaError:
                raise
            except Exception as e:
                # Convert to LuaError with traceback?
                raise LuaError(str(e))
        raise LuaError(f"attempt to call a {self.lua_type(func)} value")
    def exec_block(self, stmts, is_loop=False):
        # handle labels and goto: we need to pre-scan labels
        label_map = {}
        for idx, stmt in enumerate(stmts):
            if stmt['type'] == 'label':
                label_map[stmt['name']] = idx
        pc = 0
        # For goto, we need to handle jumps. We'll use a while loop with pc and handle GotoException
        while pc < len(stmts):
            stmt = stmts[pc]
            try:
                self.exec_stmt(stmt)
            except GotoException as e:
                if e.label in label_map:
                    pc = label_map[e.label]
                    continue
                else:
                    raise LuaError(f"no visible label '{e.label}' for <goto>")
            except BreakException:
                if is_loop:
                    raise
                else:
                    raise LuaError("break outside loop")
            pc += 1
        return None
    def exec_stmt(self, stmt):
        typ = stmt['type']
        if typ == 'local':
            # evaluate exps first
            vals = []
            for e in stmt['exps']:
                v = self.eval_exp(e)
                if isinstance(v, tuple):
                    # expand only last?
                    # For local, if multiple exps, the last can be multiple values
                    # But for simplicity, if v is tuple, expand?
                    if e == stmt['exps'][-1]:
                        # last exp expands
                        if isinstance(v, tuple):
                            vals.extend(v)
                        else:
                            vals.append(v)
                    else:
                        # only first value
                        if isinstance(v, tuple):
                            vals.append(v[0] if v else LuaNil)
                        else:
                            vals.append(v)
                else:
                    vals.append(v)
            # assign
            for i, name in enumerate(stmt['names']):
                if i < len(vals):
                    v = vals[i]
                else:
                    v = LuaNil
                self.set_var(name, v, is_local_decl=True)
