                if ':' in full:
                    # method
                    base_name, method = full.split(':',1)
                    # base_name may contain dots
                    tbl = self.get_var(base_name.split('.')[0])
                    # traverse dots for base
                    parts = base_name.split('.')
                    cur = self.get_var(parts[0])
