                if var_node['type'] == 'var':
                    self.set_var(var_node['name'], v)
                elif var_node['type'] == 'index':
                    tbl = self.eval_exp(var_node['table'])
                    key = self.eval_exp(var_node['key'])
                    if isinstance(tbl, LuaTable):
                        tbl.set(key, v)
                    elif isinstance(tbl, str):
