                handled = False
                for c, b in stmt['elseif']:
                    if self.is_truthy(self.eval_exp(c)):
                        self.push_env()
                        try:
                            self.exec_block(b)
                        finally:
                            self.pop_env()
                        handled = True
                        break
                if not handled and stmt['else'] is not None:
                    self.push_env()
                    try:
                        self.exec_block(stmt['else'])
                    finally:
                        self.pop_env()
