            self.push_env()
            try:
                while self.is_truthy(self.eval_exp(stmt['cond'])):
                    try:
                        self.exec_block(stmt['body'], is_loop=True)
                    except BreakException:
                        break
                    except ReturnException:
                        raise
            finally:
                self.pop_env()
        elif typ == 'repeat':
            self.push_env()
            try:
                while True:
                    try:
                        self.exec_block(stmt['body'], is_loop=True)
