            self.array[key-1] = value
        elif isinstance(key, int) and key == len(self.array)+1 and value is not LuaNil:
            self.array.append(value)
        else:
            if value is LuaNil:
                self.hash.pop(key, None)
            else:
                self.hash[key] = value
    def length(self):
        n = len(self.array)
        while n > 0 and self.array[n-1] is LuaNil:
            n -= 1
        return n
    def next(self, key):
        keys = []
        for i, v in enumerate(self.array):
            if v is not LuaNil:
                keys.append(i+1)
        for k, v in self.hash.items():
            if v is not LuaNil:
                keys.append(k)
        if key is LuaNil or key is None:
            if not keys:
                return LuaNil, LuaNil
            first = keys[0]
            return first, self.get(first)
        try:
            idx = keys.index(key)
        except ValueError:
            raise LuaError("invalid key to 'next'")
        if idx+1 < len(keys):
            nxt = keys[idx+1]
            return nxt, self.get(nxt)
        else:
            return LuaNil, LuaNil
    def pairs(self):
        def iter_func(state, prev):
            k, v = state.next(prev)
            if k is LuaNil:
                return ()
            return (k, v)
        return iter_func, self, LuaNil
    def ipairs(self):
        def iter_func(state, i):
            i2 = i + 1 if isinstance(i, int) else 1
            v = state.get(i2)
            if v is LuaNil:
                return ()
            return (i2, v)
        return iter_func, self, 0

class LuaFunction:
    def __init__(self, name, params, vararg, body, env, chunkname):
        self.name = name
        self.params = params
        self.vararg = vararg
        self.body = body
        self.env = env
        self.chunkname = chunkname
    def __repr__(self):
        return f"function: 0x{id(self):x}"

class LuaCoroutine:
    def __init__(self, func):
        self.func = func
        self.status = "suspended"
        self.gen = None

class LuaState:
    def __init__(self):
        self.globals = LuaTable()
        self.registry = LuaTable()
        self.warnings_on = False
        self.package = LuaTable()
        self.package.set("config", "/\n;\n?\n!\n-\n")
        self.package.set("cpath", LUA_CPATH_DEFAULT)
        self.package.set("path", LUA_PATH_DEFAULT)
        self.package.set("loaded", LuaTable())
        self.package.set("preload", LuaTable())
        searchers = LuaTable()
        # will be filled later
        self.package.set("searchers", searchers)
        self.globals.set("package", self.package)
        self.globals.set("_VERSION", VERSION_SHORT)
        self.globals.set("_G", self.globals)
        self.globals.set("_PROMPT", "> ")
        self.globals.set("_PROMPT2", ">> ")
        self.co_running = LuaCoroutine(None)
        self.co_running.status = "running"

# Lexer
class Token:
    def __init__(self, typ, val, line):
        self.typ = typ
        self.val = val
        self.line = line
    def __repr__(self):
        return f"Token({self.typ},{self.val!r},{self.line})"

class Lexer:
    def __init__(self, text, chunkname="=(command line)"):
        self.text = text
        self.pos = 0
        self.line = 1
        self.chunkname = chunkname
        self.len = len(text)
    def peek(self, n=0):
        if self.pos+n < self.len:
            return self.text[self.pos+n]
        return '\0'
    def advance(self, n=1):
        for i in range(n):
            if self.pos < self.len:
                c = self.text[self.pos]
                self.pos += 1
                if c == '\n':
                    self.line += 1
    def skip_ws(self):
        while self.pos < self.len and self.text[self.pos] in ' \t\r\n\v\f':
            self.advance()
    def next_token(self):
        self.skip_ws()
        if self.pos >= self.len:
            return Token('EOF','',self.line)
        c = self.text[self.pos]
        # long comment/string check
        if c == '-' and self.peek(1)=='-':
            if self.peek(2)=='[':
                # count =
                j=self.pos+2
                eq=0
                while j < self.len and self.text[j]=='=':
                    eq+=1; j+=1
                if j < self.len and self.text[j]=='[':
                    # long comment
                    end = ']' + '='*eq + ']'
                    self.advance(2+eq+1)
                    idx=self.text.find(end, self.pos)
                    if idx==-1:
                        self.pos=self.len
                        return self.next_token()
                    else:
                        cnt=self.text[self.pos:idx].count('\n')
                        self.line+=cnt
                        self.pos=idx+len(end)
                        return self.next_token()
            # short comment
            while self.pos < self.len and self.text[self.pos]!='\n':
                self.advance()
            return self.next_token()
        if c=='[':
            # long string
            j=self.pos
            eq=0
            k=j+1
            while k < self.len and self.text[k]=='=':
                eq+=1; k+=1
            if k < self.len and self.text[k]=='[':
                start_line=self.line
                self.advance(1+eq+1)
                end=']' + '='*eq + ']'
                idx=self.text.find(end, self.pos)
                if idx==-1:
                    raise LuaError(f"{self.chunkname}:{start_line}: unfinished long string (near '<eof>')")
                content=self.text[self.pos:idx]
                if content.startswith('\n'):
                    content=content[1:]
                elif content.startswith('\r\n'):
                    content=content[2:]
                self.line+=content.count('\n')
                # also need to count newlines in original? already
                self.pos=idx+len(end)
                return Token('STRING',content,start_line)
        if c=='"' or c=="'":
            quote=c
            start_line=self.line
            self.advance()
            s=""
            while self.pos < self.len:
                ch=self.text[self.pos]
                if ch=='\\':
                    self.advance()
                    if self.pos>=self.len: break
                    esc=self.text[self.pos]
                    self.advance()
                    if esc=='a': s+='\x07'
                    elif esc=='b': s+='\b'
                    elif esc=='f': s+='\f'
                    elif esc=='n': s+='\n'
                    elif esc=='r': s+='\r'
                    elif esc=='t': s+='\t'
                    elif esc=='v': s+='\v'
                    elif esc=='\\': s+='\\'
                    elif esc=='"': s+='"'
                    elif esc=="'": s+="'"
                    elif esc=='\n': s+='\n'
                    elif esc=='\r':
                        if self.peek()=='\n': self.advance()
                        s+='\n'
                    elif esc=='z':
                        while self.pos<self.len and self.text[self.pos] in ' \t\r\n\v\f':
                            if self.text[self.pos]=='\n': self.line+=1
                            self.advance()
                    elif esc=='x':
                        hexd=self.text[self.pos:self.pos+2]
                        if len(hexd)==2 and all(h in '0123456789abcdefABCDEF' for h in hexd):
                            s+=chr(int(hexd,16))
                            self.advance(2)
                        else:
                            raise LuaError(f"{self.chunkname}:{self.line}: hexadecimal digit expected near '\\x'")
                    elif esc=='u':
                        if self.peek()=='{':
                            self.advance()
                            start=self.pos
                            while self.pos<self.len and self.text[self.pos]!='}':
                                self.advance()
                            hexd=self.text[start:self.pos]
                            if self.pos<self.len and self.text[self.pos]=='}': self.advance()
                            try:
                                code=int(hexd,16)
                                if code>0x10FFFF: raise ValueError
                                s+=chr(code)
                            except:
                                raise LuaError(f"{self.chunkname}:{self.line}: UTF-8 value too large near '\\u'")
                        else:
                            raise LuaError(f"{self.chunkname}:{self.line}: missing '{{' near '\\u'")
                    elif esc.isdigit():
                        d=esc
                        for _ in range(2):
                            if self.pos<self.len and self.text[self.pos].isdigit():
                                d+=self.text[self.pos]
                                self.advance()
                            else: break
                        val=int(d)
                        if val>255:
                            raise LuaError(f"{self.chunkname}:{self.line}: decimal escape too large near '\\{d}'")
                        s+=chr(val)
                    else: s+=esc
                elif ch==quote:
                    self.advance()
                    break
                elif ch=='\n' or ch=='\r':
                    raise LuaError(f"{self.chunkname}:{self.line}: unfinished string near '<eof>'")
                else:
                    s+=ch
                    self.advance()
            else:
                raise LuaError(f"{self.chunkname}:{self.line}: unfinished string near '<eof>'")
            return Token('STRING',s,start_line)
        if c=='0' and self.peek(1) in 'xX':
            start=self.pos
            start_line=self.line
            self.advance(2)
            has_dot=False
            has_p=False
            while self.pos < self.len:
                ch=self.text[self.pos]
                if ch in '0123456789abcdefABCDEF':
                    self.advance()
                elif ch=='.' and not has_dot:
                    has_dot=True; self.advance()
                elif ch in 'pP' and not has_p:
                    has_p=True; self.advance()
                    if self.pos<self.len and self.text[self.pos] in '+-': self.advance()
                else: break
            num_str=self.text[start:self.pos]
            try:
                if '.' not in num_str and 'p' not in num_str.lower():
                    val=int(num_str,16)
                else:
                    val=float.fromhex(num_str)
            except: val=0
            return Token('NUMBER',val,start_line)
        if c.isdigit() or (c=='.' and self.peek(1).isdigit()):
            start=self.pos
            start_line=self.line
            has_dot=False
            has_e=False
            while self.pos < self.len:
                ch=self.text[self.pos]
                if ch.isdigit(): self.advance()
                elif ch=='.' and not has_dot and self.peek(1)!='.':
                    has_dot=True; self.advance()
                elif ch in 'eE' and not has_e:
                    has_e=True; self.advance()
                    if self.pos<self.len and self.text[self.pos] in '+-': self.advance()
                else: break
            num_str=self.text[start:self.pos]
            try:
                if '.' not in num_str and 'e' not in num_str.lower():
                    val=int(num_str)
                    if val>2**63-1 or val<-2**63:
                        val=float(num_str)
                else:
                    val=float(num_str)
            except: val=0
            return Token('NUMBER',val,start_line)
        if c.isalpha() or c=='_':
            start=self.pos
            start_line=self.line
            while self.pos<self.len and (self.text[self.pos].isalnum() or self.text[self.pos]=='_'):
                self.advance()
            name=self.text[start:self.pos]
            if name in ('and','break','do','else','elseif','end','false','for','function','goto','if','in','local','nil','not','or','repeat','return','then','true','until','while'):
                return Token(name.upper(),name,start_line)
            else:
                return Token('NAME',name,start_line)
        three=self.text[self.pos:self.pos+3]
        two=self.text[self.pos:self.pos+2]
        if three=='...':
            self.advance(3); return Token('TDOTS','...',self.line)
        if two in ('//','>>','<<','==','~=','<=','>=','::'):
            self.advance(2); return Token(two,two,self.line)
        if two=='..':
            self.advance(2); return Token('DOTDOT','..',self.line)
        self.advance()
        if c in '+-*/%^#&|~<>=(){}[];:,.':
            return Token(c,c,self.line)
        raise LuaError(f"{self.chunkname}:{self.line}: unexpected symbol near '{c}'")
    def tokenize(self):
        toks=[]
        while True:
            tok=self.next_token()
            toks.append(tok)
            if tok.typ=='EOF': break
        return toks

class Parser:
    def __init__(self, tokens, chunkname="=(command line)"):
        self.toks=tokens
        self.pos=0
        self.chunkname=chunkname
    def peek(self,n=0):
        if self.pos+n < len(self.toks): return self.toks[self.pos+n]
        return self.toks[-1]
    def advance(self):
        t=self.toks[self.pos]; self.pos+=1; return t
    def match(self, typ):
        if self.peek().typ==typ: return self.advance()
        return None
    def expect(self, typ):
        t=self.peek()
        if t.typ!=typ:
            if t.typ=='EOF':
                raise LuaError(f"{self.chunkname}:{t.line}: '{typ}' expected (to close '{typ}' at line {t.line}) near '<eof>'")
            raise LuaError(f"{self.chunkname}:{t.line}: '{typ}' expected (to close '{typ}' at line {t.line}) near '{t.val}'")
        return self.advance()
    def parse_chunk(self):
        block=self.parse_block()
        self.expect('EOF')
        return {'type':'chunk','body':block}
    def parse_block(self):
        stmts=[]
        while self.peek().typ not in ('EOF','END','ELSE','ELSEIF','UNTIL'):
            if self.peek().typ=='RETURN':
                stmts.append(self.parse_return())
                if self.peek().typ==';': self.advance()
                break
            elif self.peek().typ=='BREAK':
                self.advance()
                if self.peek().typ==';': self.advance()
                stmts.append({'type':'break'})
            elif self.peek().typ=='GOTO':
                self.advance()
                name=self.expect('NAME')
                if self.peek().typ==';': self.advance()
                stmts.append({'type':'goto','label':name.val})
            elif self.peek().typ=='::':
                self.advance()
                name=self.expect('NAME')
                self.expect('::')
                stmts.append({'type':'label','name':name.val})
            else:
                if self.peek().typ==';':
                    self.advance(); continue
                stmt=self.parse_statement()
                if stmt: stmts.append(stmt)
                if self.peek().typ==';': self.advance()
        return stmts
    def parse_return(self):
        self.expect('RETURN')
        exps=[]
        if self.peek().typ not in ('EOF','END','ELSE','ELSEIF','UNTIL',';'):
            exps=self.parse_explist()
            if self.peek().typ==';': self.advance()
        return {'type':'return','exps':exps}
    def parse_statement(self):
        t=self.peek()
        if t.typ=='LOCAL':
            return self.parse_local()
        if t.typ=='FUNCTION':
            return self.parse_functiondef()
        if t.typ=='IF': return self.parse_if()
        if t.typ=='WHILE': return self.parse_while()
        if t.typ=='REPEAT': return self.parse_repeat()
        if t.typ=='FOR': return self.parse_for()
        if t.typ=='DO':
            self.advance()
            block=self.parse_block()
            self.expect('END')
            return {'type':'do','body':block}
        saved=self.pos
        try:
            exp=self.parse_exp()
            if self.peek().typ in ('=',','):
                self.pos=saved
                return self.parse_assignment()
            else:
                if exp['type'] not in ('call','methodcall'):
                    raise LuaError(f"{self.chunkname}:{t.line}: syntax error near '{t.val}'")
                return {'type':'callstmt','call':exp}
        except LuaError:
            raise
        except:
            self.pos=saved
            return self.parse_assignment()
    def parse_local(self):
        self.expect('LOCAL')
        if self.peek().typ=='FUNCTION':
            self.advance()
            name=self.expect('NAME')
            params,vararg,body=self.parse_funcbody()
            return {'type':'localfunc','name':name.val,'params':params,'vararg':vararg,'body':body}
        else:
            names=[self.expect('NAME').val]
            while self.peek().typ==',':
                self.advance()
                names.append(self.expect('NAME').val)
            exps=[]
            if self.peek().typ=='=':
                self.advance()
                exps=self.parse_explist()
            return {'type':'local','names':names,'exps':exps}
    def parse_functiondef(self):
        self.expect('FUNCTION')
        name=self.expect('NAME').val
        is_method=False
        while self.peek().typ=='.':
            self.advance()
            n=self.expect('NAME').val
            name=name+'.'+n
        if self.peek().typ==':':
            self.advance()
            n=self.expect('NAME').val
            is_method=True
            name=name+':'+n
        params,vararg,body=self.parse_funcbody()
        if is_method: params=['self']+params
        return {'type':'functiondef','name':name,'params':params,'vararg':vararg,'body':body,'is_method':is_method}
    def parse_funcbody(self):
        self.expect('(')
        params=[]; vararg=False
        if self.peek().typ!=')':
            if self.peek().typ=='TDOTS':
                self.advance(); vararg=True
            else:
                params.append(self.expect('NAME').val)
                while self.peek().typ==',':
                    self.advance()
                    if self.peek().typ=='TDOTS':
                        self.advance(); vararg=True; break
                    else: params.append(self.expect('NAME').val)
        self.expect(')')
        block=self.parse_block()
        self.expect('END')
        return params,vararg,block
    def parse_if(self):
        self.expect('IF')
        cond=self.parse_exp()
        self.expect('THEN')
        then_block=self.parse_block()
        elseif_blocks=[]
        else_block=None
        while self.peek().typ=='ELSEIF':
            self.advance()
            c=self.parse_exp()
            self.expect('THEN')
            b=self.parse_block()
            elseif_blocks.append((c,b))
        if self.peek().typ=='ELSE':
            self.advance()
            else_block=self.parse_block()
        self.expect('END')
        return {'type':'if','cond':cond,'then':then_block,'elseif':elseif_blocks,'else':else_block}
    def parse_while(self):
        self.expect('WHILE')
        cond=self.parse_exp()
        self.expect('DO')
        body=self.parse_block()
        self.expect('END')
        return {'type':'while','cond':cond,'body':body}
    def parse_repeat(self):
        self.expect('REPEAT')
        body=self.parse_block()
        self.expect('UNTIL')
        cond=self.parse_exp()
        return {'type':'repeat','body':body,'cond':cond}
    def parse_for(self):
        self.expect('FOR')
        name=self.expect('NAME').val
        if self.peek().typ=='=':
            self.advance()
            start=self.parse_exp()
            self.expect(',')
            limit=self.parse_exp()
            step=None
            if self.peek().typ==',':
                self.advance()
                step=self.parse_exp()
            self.expect('DO')
            body=self.parse_block()
            self.expect('END')
            return {'type':'fornum','var':name,'start':start,'limit':limit,'step':step,'body':body}
        else:
            names=[name]
            while self.peek().typ==',':
                self.advance()
                names.append(self.expect('NAME').val)
            self.expect('IN')
            exps=self.parse_explist()
            self.expect('DO')
            body=self.parse_block()
            self.expect('END')
            return {'type':'forin','names':names,'exps':exps,'body':body}
    def parse_assignment(self):
        vars=[self.parse_var()]
        while self.peek().typ==',':
            self.advance()
            vars.append(self.parse_var())
        self.expect('=')
        exps=self.parse_explist()
        return {'type':'assign','vars':vars,'exps':exps}
    def parse_var(self):
        exp=self.parse_prefixexp()
        return exp
    def parse_explist(self):
        exps=[self.parse_exp()]
        while self.peek().typ==',':
            self.advance()
            exps.append(self.parse_exp())
        return exps
    def parse_exp(self, min_prec=0):
        tok=self.peek()
        if tok.typ in ('NOT','#','-','~'):
            self.advance()
            rhs=self.parse_exp(12)
            left={'type':'unary','op':tok.val,'exp':rhs}
        elif tok.typ=='TDOTS':
            self.advance()
            left={'type':'vararg'}
        elif tok.typ=='NIL':
            self.advance()
            left={'type':'nil'}
        elif tok.typ=='TRUE':
            self.advance()
            left={'type':'boolean','val':True}
        elif tok.typ=='FALSE':
            self.advance()
            left={'type':'boolean','val':False}
        elif tok.typ=='NUMBER':
            self.advance()
            left={'type':'number','val':tok.val}
        elif tok.typ=='STRING':
            self.advance()
            left={'type':'string','val':tok.val}
        elif tok.typ=='FUNCTION':
            self.advance()
            params,vararg,body=self.parse_funcbody()
            left={'type':'function','params':params,'vararg':vararg,'body':body}
        elif tok.typ=='{':
            left=self.parse_tableconstructor()
        elif tok.typ=='(':
            self.advance()
            exp=self.parse_exp()
            self.expect(')')
            left=exp
        elif tok.typ=='NAME':
            left=self.parse_prefixexp()
        else:
            raise LuaError(f"{self.chunkname}:{tok.line}: unexpected symbol near '{tok.val}'")
        while True:
            op=self.peek()
            prec=self.get_prec(op.typ if op.typ in ('AND','OR') else op.val)
            if prec is None or prec < min_prec: break
            is_right=op.val in ('^','..')
            next_prec=prec if is_right else prec+1
            self.advance()
            rhs=self.parse_exp(next_prec)
            left={'type':'binary','op':op.val,'left':left,'right':rhs}
        return left
    def get_prec(self, op):
        if op=='or': return 1
        if op=='and': return 2
        if op in ('<','>','<=','>=','~=', '=='): return 3
        if op=='|': return 4
        if op=='~': return 5
        if op=='&': return 6
        if op in ('<<','>>'): return 7
        if op=='..': return 8
        if op in ('+','-'): return 9
        if op in ('*','/','//','%'): return 10
        if op=='^': return 12
        return None
    def parse_prefixexp(self):
        if self.peek().typ=='(':
            self.advance()
            exp=self.parse_exp()
            self.expect(')')
            base=exp
        elif self.peek().typ=='NAME':
            name=self.advance().val
            base={'type':'var','name':name}
        else:
            raise LuaError(f"{self.chunkname}:{self.peek().line}: unexpected symbol near '{self.peek().val}'")
        while True:
            if self.peek().typ=='.':
                self.advance()
                field=self.expect('NAME').val
                base={'type':'index','table':base,'key':{'type':'string','val':field}}
            elif self.peek().typ=='[':
                self.advance()
                idx=self.parse_exp()
                self.expect(']')
                base={'type':'index','table':base,'key':idx}
            elif self.peek().typ==':':
                self.advance()
                method=self.expect('NAME').val
                args=self.parse_args()
                base={'type':'methodcall','table':base,'method':method,'args':args}
            elif self.peek().typ in ('(','{','STRING'):
                args=self.parse_args()
                base={'type':'call','func':base,'args':args}
            else: break
        return base
    def parse_args(self):
        if self.peek().typ=='(':
            self.advance()
            args=[]
            if self.peek().typ!=')':
                args=self.parse_explist()
            self.expect(')')
            return args
        elif self.peek().typ=='{':
            t=self.parse_tableconstructor()
            return [t]
        elif self.peek().typ=='STRING':
            s=self.advance()
            return [{'type':'string','val':s.val}]
        else:
            raise LuaError(f"{self.chunkname}:{self.peek().line}: function arguments expected near '{self.peek().val}'")
    def parse_tableconstructor(self):
        self.expect('{')
        fields=[]
        while self.peek().typ!='}':
            if self.peek().typ=='EOF':
                raise LuaError(f"{self.chunkname}:{self.peek().line}: '}}' expected (to close '{{' at line {self.peek().line}) near '<eof>'")
            if self.peek().typ=='[':
                self.advance()
                k=self.parse_exp()
                self.expect(']')
                self.expect('=')
                v=self.parse_exp()
                fields.append({'type':'field_kv','key':k,'val':v})
            elif self.peek().typ=='NAME' and self.peek(1).typ=='=':
                k=self.advance().val
                self.advance()
                v=self.parse_exp()
                fields.append({'type':'field_kv','key':{'type':'string','val':k},'val':v})
            else:
                v=self.parse_exp()
                fields.append({'type':'field_val','val':v})
            if self.peek().typ in (',',';'):
                self.advance()
        self.expect('}')
        return {'type':'table','fields':fields}

class ReturnException(Exception):
    def __init__(self, vals): self.vals=vals
class BreakException(Exception): pass
class GotoException(Exception):
    def __init__(self, label): self.label=label

class Interpreter:
    def __init__(self, state, chunkname):
        self.state=state
        self.chunkname=chunkname
        self.env_stack=[{}]
        self.is_main=False
    def push_env(self): self.env_stack.append({})
    def pop_env(self): self.env_stack.pop()
    def get_var(self, name):
        for scope in reversed(self.env_stack):
            if name in scope:
                return scope[name]
        v=self.state.globals.get(name)
        if v is not LuaNil: return v
        return LuaNil
    def set_var(self, name, val, is_local_decl=False):
        if is_local_decl:
            self.env_stack[-1][name]=val
            return
        for scope in reversed(self.env_stack):
            if name in scope:
                scope[name]=val
                return
        self.state.globals.set(name,val)
    def is_truthy(self, v): return not (v is LuaNil or v is False)
    def lua_type(self, v):
        if v is LuaNil: return "nil"
        if isinstance(v, bool): return "boolean"
        if isinstance(v, (int,float)): return "number"
        if isinstance(v, str): return "string"
        if isinstance(v, LuaTable): return "table"
        if isinstance(v, LuaFunction) or callable(v): return "function"
        if isinstance(v, LuaCoroutine): return "thread"
        return "userdata"
    def eval_exp(self, node):
        typ=node['type']
        if typ=='nil': return LuaNil
        if typ=='boolean': return node['val']
        if typ=='number': return node['val']
        if typ=='string': return node['val']
        if typ=='var': return self.get_var(node['name'])
        if typ=='vararg': return LuaNil
        if typ=='table':
            tbl=LuaTable()
            array_idx=1
            for f in node['fields']:
                if f['type']=='field_val':
                    v=self.eval_exp(f['val'])
                    if isinstance(v, tuple):
                        for vi in v:
                            tbl.set(array_idx, vi)
                            array_idx+=1
                    else:
                        tbl.set(array_idx, v)
                        array_idx+=1
                elif f['type']=='field_kv':
                    k=self.eval_exp(f['key'])
                    v=self.eval_exp(f['val'])
                    tbl.set(k,v)
            return tbl
        if typ=='index':
            tbl=self.eval_exp(node['table'])
            key=self.eval_exp(node['key'])
            if isinstance(tbl, LuaTable):
                return tbl.get(key)
            if isinstance(tbl, str):
                return LuaNil
            return LuaNil
        if typ=='unary':
            op=node['op']; val=self.eval_exp(node['exp'])
            if op=='not': return False if self.is_truthy(val) else True
            if op=='#':
                if isinstance(val, LuaTable): return val.length()
                if isinstance(val, str): return len(val)
                raise LuaError(f"attempt to get length of a {self.lua_type(val)} value")
            if op=='-':
                if isinstance(val,(int,float)): return -val
                raise LuaError(f"attempt to perform arithmetic on a {self.lua_type(val)} value")
            if op=='~':
                if isinstance(val,int): return ~val
                raise LuaError(f"attempt to perform bitwise operation on a {self.lua_type(val)} value")
            raise LuaError(f"unknown unary {op}")
        if typ=='binary':
            op=node['op']
            if op=='and':
                left=self.eval_exp(node['left'])
                if not self.is_truthy(left): return left
                else: return self.eval_exp(node['right'])
            if op=='or':
                left=self.eval_exp(node['left'])
                if self.is_truthy(left): return left
                else: return self.eval_exp(node['right'])
            left=self.eval_exp(node['left'])
            right=self.eval_exp(node['right'])
            return self.eval_binary(op,left,right)
        if typ=='call':
            func=self.eval_exp(node['func'])
            args=[]
            for a in node['args']:
                v=self.eval_exp(a)
                if isinstance(v, tuple):
                    args.extend(v)
                else: args.append(v)
            return self.call_func(func,args,node)
        if typ=='methodcall':
            tbl=self.eval_exp(node['table'])
            method=node['method']
            func=None
            if isinstance(tbl, LuaTable):
                func=tbl.get(method)
            elif isinstance(tbl, str):
                str_lib=self.state.globals.get("string")
                if isinstance(str_lib, LuaTable):
                    func=str_lib.get(method)
            args=[tbl]
            for a in node['args']:
                v=self.eval_exp(a)
                if isinstance(v, tuple): args.extend(v)
                else: args.append(v)
            return self.call_func(func,args,node)
        if typ=='function':
            fn=LuaFunction(None,node['params'],node['vararg'],node['body'],dict(self.env_stack[-1]),self.chunkname)
            return fn
        raise LuaError(f"unknown exp type {typ}")
    def eval_binary(self, op,a,b):
        def to_number(v):
            if isinstance(v,(int,float)): return v
            if isinstance(v,str):
                try:
                    if '.' in v or 'e' in v.lower():
                        return float(v)
                    else: return int(v)
                except: return None
            return None
        if op in ('+','-','*','/','%','^','//'):
            na=to_number(a); nb=to_number(b)
            if na is None or nb is None:
                raise LuaError(f"attempt to perform arithmetic on a {self.lua_type(a)} value")
            if op=='+': return na+nb
            if op=='-': return na-nb
            if op=='*': return na*nb
            if op=='/': return float(na)/float(nb)
            if op=='//': return math.floor(float(na)/float(nb))
            if op=='%': return na % nb
            if op=='^': return na ** nb
        if op=='..':
            sa=self.number_to_string(a) if isinstance(a,(int,float)) else (a if isinstance(a,str) else lua_tostring(a))
            sb=self.number_to_string(b) if isinstance(b,(int,float)) else (b if isinstance(b,str) else lua_tostring(b))
            # need to ensure a,b are strings or numbers
            if not isinstance(a,(str,int,float)) or not isinstance(b,(str,int,float)):
                raise LuaError(f"attempt to concatenate a {self.lua_type(a)} value")
            return sa+sb
        if op in ('<<','>>','&','|','~'):
            if not isinstance(a,int) or not isinstance(b,int):
                if isinstance(a,float) and a.is_integer(): a=int(a)
                elif isinstance(a,str):
                    try: a=int(a)
                    except: raise LuaError(f"attempt to perform bitwise operation on a {self.lua_type(a)} value")
                else: raise LuaError(f"attempt to perform bitwise operation on a {self.lua_type(a)} value")
                if isinstance(b,float) and b.is_integer(): b=int(b)
                elif isinstance(b,str):
                    try: b=int(b)
                    except: raise LuaError(f"attempt to perform bitwise operation on a {self.lua_type(b)} value")
                else: raise LuaError(f"attempt to perform bitwise operation on a {self.lua_type(b)} value")
            if op=='<<': return a<<b
            if op=='>>': return a>>b
            if op=='&': return a & b
            if op=='|': return a | b
            if op=='~': return a ^ b
        if op in ('==','~=','<','>','<=','>='):
            if op=='==':
                if type(a)!=type(b):
                    if isinstance(a,(int,float)) and isinstance(b,(int,float)): return a==b
                    return False
                return a==b
            if op=='~=':
                if type(a)!=type(b):
                    if isinstance(a,(int,float)) and isinstance(b,(int,float)): return a!=b
                    return True
                return a!=b
            if isinstance(a,(int,float)) and isinstance(b,(int,float)):
                if op=='<': return a < b
                if op=='>': return a > b
                if op=='<=': return a <= b
                if op=='>=': return a >= b
            if isinstance(a,str) and isinstance(b,str):
                if op=='<': return a < b
                if op=='>': return a > b
                if op=='<=': return a <= b
                if op=='>=': return a >= b
            raise LuaError(f"attempt to compare {self.lua_type(a)} with {self.lua_type(b)}")
        raise LuaError(f"unknown binary op {op}")
    def number_to_string(self, n):
        if isinstance(n,int): return str(n)
        s=str(n)
        return s
    def call_func(self, func, args, call_node=None):
        if func is LuaNil or func is None:
            raise LuaError("attempt to call a nil value")
        if isinstance(func, LuaTable):
            mt=func.metatable
            if mt is not None and isinstance(mt, LuaTable):
                call=mt.get("__call")
                if call is not LuaNil:
                    return self.call_func(call,[func]+args,call_node)
            raise LuaError(f"attempt to call a {self.lua_type(func)} value")
        if isinstance(func, LuaFunction):
            old_stack=self.env_stack
            new_env={}
            for i, pname in enumerate(func.params):
                if i < len(args):
                    new_env[pname]=args[i]
                else:
                    new_env[pname]=LuaNil
            if func.vararg:
                varargs=args[len(func.params):]
                new_env['...']=varargs
            self.env_stack=self.env_stack+[new_env]
            try:
                result=self.exec_block(func.body)
                if result is None: return LuaNil
                if isinstance(result, tuple):
                    if len(result)==0: return LuaNil
                    if len(result)==1: return result[0]
                    return result
                return result
            except ReturnException as e:
                vals=e.vals
                if not vals: return LuaNil
                if len(vals)==1: return vals[0]
                return tuple(vals)
            finally:
                self.env_stack=old_stack
        if callable(func):
            try:
                if hasattr(func,'_is_lua_stdlib'):
                    return func(*args)
                else:
                    res=func(*args)
                    if res is None: return LuaNil
                    return res
            except LuaError:
                raise
            except Exception as e:
                raise LuaError(str(e))
        raise LuaError(f"attempt to call a {self.lua_type(func)} value")
    def exec_block(self, stmts, is_loop=False):
        label_map={}
        for idx, stmt in enumerate(stmts):
            if stmt['type']=='label':
                label_map[stmt['name']]=idx
        pc=0
        while pc < len(stmts):
            stmt=stmts[pc]
            try:
                self.exec_stmt(stmt)
            except GotoException as e:
                if e.label in label_map:
                    pc=label_map[e.label]
                    continue
                else:
                    raise LuaError(f"no visible label '{e.label}' for <goto>")
            except BreakException:
                if is_loop: raise
                else: raise LuaError("break outside loop")
            pc+=1
        return None
    def exec_stmt(self, stmt):
        typ=stmt['type']
        if typ=='local':
            vals=[]
            for e in stmt['exps']:
                v=self.eval_exp(e)
                if isinstance(v, tuple):
                    if e==stmt['exps'][-1]:
                        vals.extend(v)
                    else:
                        vals.append(v[0] if v else LuaNil)
                else: vals.append(v)
            for i, name in enumerate(stmt['names']):
                v=vals[i] if i < len(vals) else LuaNil
                self.set_var(name,v,is_local_decl=True)
        elif typ=='localfunc':
            fn=LuaFunction(stmt['name'],stmt['params'],stmt['vararg'],stmt['body'],dict(self.env_stack[-1]),self.chunkname)
            self.set_var(stmt['name'],fn,is_local_decl=True)
        elif typ=='functiondef':
            fn=LuaFunction(stmt['name'],stmt['params'],stmt['vararg'],stmt['body'],dict(self.env_stack[-1]),self.chunkname)
            if '.' in stmt['name'] or ':' in stmt['name']:
                full=stmt['name']
                if ':' in full:
                    base_name, method=full.split(':',1)
                    parts=base_name.split('.')
                    cur=self.get_var(parts[0])
                    for p in parts[1:]:
                        if isinstance(cur, LuaTable):
                            cur=cur.get(p)
                        else: cur=LuaNil
                    if isinstance(cur, LuaTable):
                        cur.set(method,fn)
                    else:
                        raise LuaError(f"attempt to index a {self.lua_type(cur)} value")
                else:
                    parts=full.split('.')
                    cur=self.get_var(parts[0])
                    if cur is LuaNil:
                        cur=LuaTable()
                        self.set_var(parts[0],cur)
                    for p in parts[1:-1]:
                        nxt=cur.get(p)
                        if nxt is LuaNil:
                            nxt=LuaTable()
                            cur.set(p,nxt)
                        cur=nxt
                    cur.set(parts[-1],fn)
            else:
                self.set_var(stmt['name'],fn)
        elif typ=='assign':
            vals=[]
            for e in stmt['exps']:
                v=self.eval_exp(e)
                if isinstance(v, tuple):
                    if e==stmt['exps'][-1]:
                        vals.extend(v)
                    else:
                        vals.append(v[0] if v else LuaNil)
                else: vals.append(v)
            for i, var_node in enumerate(stmt['vars']):
                v=vals[i] if i < len(vals) else LuaNil
                if var_node['type']=='var':
                    self.set_var(var_node['name'],v)
                elif var_node['type']=='index':
                    tbl=self.eval_exp(var_node['table'])
                    key=self.eval_exp(var_node['key'])
                    if isinstance(tbl, LuaTable):
                        tbl.set(key,v)
                    else:
                        raise LuaError(f"attempt to index a {self.lua_type(tbl)} value")
                else: raise LuaError("unknown var type")
        elif typ=='callstmt':
            self.eval_exp(stmt['call'])
        elif typ=='if':
            cond=self.eval_exp(stmt['cond'])
            if self.is_truthy(cond):
                self.push_env()
                try: self.exec_block(stmt['then'])
                finally: self.pop_env()
            else:
                handled=False
                for c,b in stmt['elseif']:
                    if self.is_truthy(self.eval_exp(c)):
                        self.push_env()
                        try: self.exec_block(b)
                        finally: self.pop_env()
                        handled=True; break
                if not handled and stmt['else'] is not None:
                    self.push_env()
                    try: self.exec_block(stmt['else'])
                    finally: self.pop_env()
        elif typ=='while':
            self.push_env()
            try:
                while self.is_truthy(self.eval_exp(stmt['cond'])):
                    try: self.exec_block(stmt['body'], is_loop=True)
                    except BreakException: break
            finally: self.pop_env()
        elif typ=='repeat':
            self.push_env()
            try:
                while True:
                    try: self.exec_block(stmt['body'], is_loop=True)
                    except BreakException: break
                    if self.is_truthy(self.eval_exp(stmt['cond'])): break
            finally: self.pop_env()
        elif typ=='fornum':
            start=self.eval_exp(stmt['start'])
            limit=self.eval_exp(stmt['limit'])
            step=self.eval_exp(stmt['step']) if stmt['step'] else 1
            start=self.to_number(start); limit=self.to_number(limit); step=self.to_number(step)
            if not isinstance(start,(int,float)) or not isinstance(limit,(int,float)) or not isinstance(step,(int,float)):
                raise LuaError("bad argument #2 to 'for' (number expected)")
            self.push_env()
            try:
                i=start
                cond=lambda: i<=limit if step>0 else i>=limit
                while cond():
                    self.env_stack[-1][stmt['var']]=i
                    try: self.exec_block(stmt['body'], is_loop=True)
                    except BreakException: break
                    i+=step
            finally: self.pop_env()
        elif typ=='forin':
            vals=[]
            for e in stmt['exps']:
                v=self.eval_exp(e)
                if isinstance(v, tuple):
                    if e==stmt['exps'][-1]: vals.extend(v)
                    else: vals.append(v[0] if v else LuaNil)
                else: vals.append(v)
            while len(vals)<3: vals.append(LuaNil)
            iter_func, state_var, var=vals[0],vals[1],vals[2]
            self.push_env()
            try:
                while True:
                    res=self.call_func(iter_func,[state_var,var],None)
                    if isinstance(res, tuple):
                        if not res or res[0] is LuaNil: break
                        for i, name in enumerate(stmt['names']):
                            if i < len(res): self.env_stack[-1][name]=res[i]
                            else: self.env_stack[-1][name]=LuaNil
                        var=res[0]
                    else:
                        if res is LuaNil: break
                        if stmt['names']:
                            self.env_stack[-1][stmt['names'][0]]=res
                            var=res
                        for name in stmt['names'][1:]: self.env_stack[-1][name]=LuaNil
                    try: self.exec_block(stmt['body'], is_loop=True)
                    except BreakException: break
            finally: self.pop_env()
        elif typ=='do':
            self.push_env()
            try: self.exec_block(stmt['body'])
            finally: self.pop_env()
        elif typ=='return':
            vals=[]
            for e in stmt['exps']:
                v=self.eval_exp(e)
                if isinstance(v, tuple):
                    if e==stmt['exps'][-1]: vals.extend(v)
                    else: vals.append(v[0] if v else LuaNil)
                else: vals.append(v)
            raise ReturnException(vals)
        elif typ=='break': raise BreakException()
        elif typ=='goto': raise GotoException(stmt['label'])
        elif typ=='label': pass
        else: raise LuaError(f"unknown stmt {typ}")
    def to_number(self, v):
        if isinstance(v,(int,float)): return v
        if isinstance(v,str):
            try:
                if '.' in v or 'e' in v.lower(): return float(v)
                else: return int(v)
            except: return LuaNil
        return LuaNil

def lua_tostring(v):
    if v is LuaNil: return "nil"
    if v is True: return "true"
    if v is False: return "false"
    if isinstance(v,(int,float)): return str(v)
    if isinstance(v,str): return v
    if isinstance(v, LuaTable): return f"table: 0x{id(v):x}"
    if isinstance(v, LuaFunction): return f"function: 0x{id(v):x}"
    if isinstance(v, LuaCoroutine): return f"thread: 0x{id(v):x}"
    return str(v)

def state_to_string(v, state):
    # need to handle __tostring?
    if isinstance(v, LuaTable) and v.metatable is not None:
        mt=v.metatable.get("__tostring")
        if mt is not LuaNil and callable(mt):
            # need to call mt via interpreter? For now, just call
            try:
                # create dummy interpreter
                # we have state, but need interpreter instance; hack: if mt is LuaFunction, need to call via Interpreter?
                # For now, just return default
                pass
            except: pass
    return lua_tostring(v)

def setup_stdlib(state):
    # base
    def lua_print(*args):
        out="\t".join(state_to_string(a, state) for a in args)
        sys.stdout.write(out + "\n")
        sys.stdout.flush()
        return LuaNil
    lua_print._is_lua_stdlib=True
    state.globals.set("print", lua_print)
    def lua_type(v):
        if v is LuaNil: return "nil"
        if isinstance(v,bool): return "boolean"
        if isinstance(v,(int,float)): return "number"
        if isinstance(v,str): return "string"
        if isinstance(v, LuaTable): return "table"
        if isinstance(v,(LuaFunction,)) or callable(v): return "function"
        if isinstance(v, LuaCoroutine): return "thread"
        return "userdata"
    lua_type._is_lua_stdlib=True
    state.globals.set("type", lua_type)
    def lua_tostring_func(v):
        return state_to_string(v, state)
    lua_tostring_func._is_lua_stdlib=True
    state.globals.set("tostring", lua_tostring_func)
    def lua_tonumber(v, base=10):
        if isinstance(v,(int,float)): return v
        if isinstance(v,str):
            v=v.strip()
            try:
                if base==10:
                    if '.' in v or 'e' in v.lower():
                        return float(v)
                    if v.lower().startswith('0x'):
                        return int(v,16)
                    return int(v) if v.lstrip('-').isdigit() else float(v) if v.replace('.','',1).lstrip('-').isdigit() else LuaNil
                else:
                    return int(v, base)
            except: return LuaNil
        return LuaNil
    lua_tonumber._is_lua_stdlib=True
    state.globals.set("tonumber", lua_tonumber)
    def lua_error(msg, level=1):
        raise LuaError(str(msg) if msg is not LuaNil else "nil")
    lua_error._is_lua_stdlib=True
    state.globals.set("error", lua_error)
    def lua_assert(v, msg="assertion failed!"):
        if not (v is not LuaNil and v is not False):
            raise LuaError(str(msg))
        return v
    lua_assert._is_lua_stdlib=True
    state.globals.set("assert", lua_assert)
    def lua_select(index, *args):
        if isinstance(index, str) and index=="#":
            return len(args)
        if index=="#": return len(args)
        try: n=int(index)
        except: raise LuaError("bad argument #1 to 'select' (number expected, got string)")
        if n <0: n=len(args)+n+1
        if n<1 or n>len(args): raise LuaError("bad argument #1 to 'select' (index out of range)")
        res=args[n-1:]
        if len(res)==1: return res[0]
        return tuple(res) if res else LuaNil
    lua_select._is_lua_stdlib=True
    state.globals.set("select", lua_select)
    def lua_getmetatable(v):
        if isinstance(v, LuaTable):
            return v.metatable if v.metatable is not None else LuaNil
        return LuaNil
    lua_getmetatable._is_lua_stdlib=True
    state.globals.set("getmetatable", lua_getmetatable)
    def lua_setmetatable(t, mt):
        if not isinstance(t, LuaTable): raise LuaError("bad argument #1 to 'setmetatable' (table expected)")
        if mt is not LuaNil and not isinstance(mt, LuaTable): raise LuaError("bad argument #2 to 'setmetatable' (nil or table expected)")
        if t.metatable is not None:
            protected=t.metatable.get("__metatable")
            if protected is not LuaNil: raise LuaError("cannot change a protected metatable")
        t.metatable=None if mt is LuaNil else mt
        return t
    lua_setmetatable._is_lua_stdlib=True
    state.globals.set("setmetatable", lua_setmetatable)
    def lua_rawequal(a,b): return a is b or a==b
    lua_rawequal._is_lua_stdlib=True
    state.globals.set("rawequal", lua_rawequal)
    def lua_rawget(t,k):
        if not isinstance(t, LuaTable): raise LuaError("bad argument #1 to 'rawget' (table expected)")
        return t.rawget(k)
    lua_rawget._is_lua_stdlib=True
    state.globals.set("rawget", lua_rawget)
    def lua_rawset(t,k,v):
        if not isinstance(t, LuaTable): raise LuaError("bad argument #1 to 'rawset' (table expected)")
        t.rawset(k,v)
        return t
    lua_rawset._is_lua_stdlib=True
    state.globals.set("rawset", lua_rawset)
    def lua_rawlen(v):
        if isinstance(v, LuaTable): return v.length()
        if isinstance(v, str): return len(v)
        raise LuaError(f"attempt to get length of a {lua_type(v)} value")
    lua_rawlen._is_lua_stdlib=True
    state.globals.set("rawlen", lua_rawlen)
    def lua_next(t,k):
        if not isinstance(t, LuaTable): raise LuaError("bad argument #1 to 'next' (table expected)")
        return t.next(k)
    lua_next._is_lua_stdlib=True
    state.globals.set("next", lua_next)
    def lua_pairs(t):
        if not isinstance(t, LuaTable): raise LuaError("bad argument #1 to 'pairs' (table expected)")
        if t.metatable is not None:
            mm=t.metatable.get("__pairs")
